package store

import (
	"context"
	"errors"
	"testing"
)

type gsrWitnessReader struct {
	calls int
}

func (r *gsrWitnessReader) Read(ctx context.Context, key string) (string, error) {
	r.calls++
	if err := ctx.Err(); err != nil {
		return "", err
	}
	return "", ErrRetry
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	r := &gsrWitnessReader{}
	_, err := Fetch(ctx, r, "key")

	if r.calls != 1 {
		t.Fatalf("Read called %d times, want 1", r.calls)
	}
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("Fetch returned error %v, want context.Canceled", err)
	}
}

