type gsrWitnessReader struct {
	calls int
}

// Read honours the contract that real implementations follow by returning
// the context error if the context is cancelled.
func (r *gsrWitnessReader) Read(ctx context.Context, key string) (string, error) {
	r.calls++
	if err := ctx.Err(); err != nil {
		return "", err
	}
	return "", ErrRetry
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // Context is already cancelled

	r := &gsrWitnessReader{}
	_, err := Fetch(ctx, r, "test-key")

	if r.calls != 1 {
		t.Fatalf("Fetch(cancelledCtx) made %d reads, want 1", r.calls)
	}
	if err != context.Canceled {
		t.Fatalf("Fetch(cancelledCtx) error = %v, want context.Canceled", err)
	}
}

