package recruiter

import (
	"context"
	"errors"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessFakeStorage struct {
	storage.Client
	cancel context.CancelFunc
	writes int
}

func (f *gsrWitnessFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	// Return a valid JSON object so unmarshaling succeeds.
	return []byte(`{}`), "etag1", nil
}

func (f *gsrWitnessFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	f.writes++
	if f.cancel != nil {
		// Simulate context cancellation during or right before the sleep
		f.cancel()
	}
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	f := &gsrWitnessFakeStorage{cancel: cancel}
	s := &Store{
		Storage: f,
		Bucket:  "test-bucket",
	}

	_, err := s.Mutate(ctx, "https://linkedin.com/in/jane", func(c Contact) Contact {
		return c
	})

	if !errors.Is(err, context.Canceled) {
		t.Fatalf("Mutate() error = %v, want error wrapping context.Canceled", err)
	}
	if f.writes >= maxWriteRetries {
		t.Fatalf("WriteFile called %d times, expected the retry loop to abort early without exhausting maxWriteRetries", f.writes)
	}
}

