	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrMockStorage struct {
	storage.Client
	writes int
	cancel context.CancelFunc
}

func (m *gsrMockStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	return nil, "", storage.ErrNotFound
}

func (m *gsrMockStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	m.writes++
	if m.cancel != nil {
		m.cancel()
	}
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	mock := &gsrMockStorage{cancel: cancel}
	store := &Store{
		Storage: mock,
		Bucket:  "test-bucket",
	}

	_, err := store.Mutate(ctx, "https://url", func(c Contact) Contact { return c })

	if err == nil {
		t.Fatalf("Mutate() returned nil error, want context error")
	}
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("Mutate() err = %v, want it to wrap context.Canceled", err)
	}
	if mock.writes >= maxWriteRetries {
		t.Fatalf("Mutate() did %d writes, exhausting retries despite context cancellation", mock.writes)
	}
}

package recruiter

import (
	"context"
	"errors"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrWitnessFakeStorage struct {
	storage.Client
	writeCalls int
	cancel     context.CancelFunc
}

func (f *gsrWitnessFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	// Return valid JSON for an empty map so it unmarshals successfully.
	return []byte("{}"), "etag1", nil
}

func (f *gsrWitnessFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	f.writeCalls++
	// Cancel the context right before returning an ETag mismatch.
	// This simulates the context being cancelled just as we head into the sleep.
	if f.cancel != nil {
		f.cancel()
	}
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	fs := &gsrWitnessFakeStorage{cancel: cancel}
	s := &Store{Storage: fs, Bucket: "test-bucket"}

	// If the claim is true, it keeps retrying until maxWriteRetries is exhausted,
	// and writeCalls would be 5 (or at least >1).
	_, err := s.Mutate(ctx, "https://linkedin.com/in/test", func(c Contact) Contact { return c })

	// Verify the retry loop actually aborted early by catching context.Canceled on the next read iteration.
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("Mutate() err = %v, want error wrapping context.Canceled", err)
	}
	if fs.writeCalls != 1 {
		t.Fatalf("WriteFile called %d times, want exactly 1 (meaning it aborted early without exhausting retries)", fs.writeCalls)
	}
}
